import{_ as h,l as i,o as n,c as l,v as s,p as d,x as r,d as t,i as u,S as p,b as a}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"双重机器学习 DML","description":"","frontmatter":{"title":"双重机器学习 DML","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/double-machine-learning.md","filePath":"quant/double-machine-learning.md","lastUpdated":1789023840000}'),m={name:"quant/double-machine-learning.md"};function E(D,e,c,g,b,A){const o=i("Mermaid");return n(),l("div",null,[e[1]||(e[1]=s('<h1 id="双重机器学习-dml" tabindex="-1">双重机器学习 DML <a class="header-anchor" href="#双重机器学习-dml" aria-label="Permalink to &quot;双重机器学习 DML&quot;">​</a></h1><div class="epigraph"><p>目标参数可以在讨厌参数用灵活机器学习估计时仍以根号 n 速率推断，前提是得分对讨厌参数的扰动正交，并且交叉拟合切断了过拟合路径。</p><footer>—— Chernozhukov, Chetverikov, Demirer, Duflo, Hansen, Newey and Robins, Double/Debiased Machine Learning for Treatment and Structural Parameters, The Econometrics Journal, 2018</footer></div><p>资产定价和事件研究经常要估一个低维对象：某个处理的平均效应、某个制度变量的结构系数、在灵活控制了一大堆特征之后「还剩多少」。普通做法是把处理 \\(D\\) 和特征 \\(X\\) 一起丢进正则回归或树，再读 \\(D\\) 的系数。正则、早停和过拟合会把这一系数拉向零或拉向噪声，常规标准误也不再成立。Chernozhukov 等人把半参数计量里的 Neyman 正交与样本分割写成一套可操作的双重机器学习（Double/Debiased Machine Learning, DML）：先用任意好的机器学习估讨厌函数，再在正交得分上对目标参数做低维估计。它回答的是识别与推断，不是又一条截面 alpha。与 <a href="/quant/fama-macbeth">Fama–MacBeth</a> 的风险溢价、<a href="/quant/regularized-linear-alpha">正则线性</a> 的预测系数，对象不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>部分线性模型写</p> \\[Y = D\\theta_0 + g_0(X) + U, \\qquad D = m_0(X) + V, \\]<p>其中 \\(\\mathbb{E}[U\\mid D,X]=0\\)，\\(\\mathbb{E}[V\\mid X]=0\\)。\\(\\theta_0\\) 是目标，\\(g_0\\) 与 \\(m_0\\) 是讨厌函数。若 \\(g_0\\) 用 LASSO、随机森林或神经网络估计，再把 \\(Y-\\hat g(X)\\) 对 \\(D\\) 回归，会留下两块偏差：正则化把 \\(g\\) 估偏，过拟合让 \\(\\hat g\\) 吃进一部分 \\(D\\) 的变异。Chernozhukov 等人强调，朴素「ML 控制再读系数」一般达不到 \\(\\sqrt{n}\\) 推断。金融截面里 \\(X\\) 动辄上百列、信噪比低，这个问题比教科书回归更尖锐。</p><p>处理效应的交互模型同样适用：潜在结果 \\(Y(d)\\)，在无混杂 \\(\\mathbb{E}[Y(d)\\mid X]=g(d,X)\\) 与重叠下，平均处理效应是 \\(g(1,X)-g(0,X)\\) 的期望。讨厌函数变成两个回归和一个倾向得分。DML 的主张不是「用了机器学习所以因果」，而是：在识别假设已经写清楚之后，把讨厌函数的估计误差从目标得分里正交掉。</p><h3 id="正交得分在防什么" tabindex="-1">正交得分在防什么 <a class="header-anchor" href="#正交得分在防什么" aria-label="Permalink to &quot;正交得分在防什么&quot;">​</a></h3><p>Neyman 正交要求得分 \\(\\psi\\) 在讨厌参数的真值处，对讨厌参数的 Gateaux 导数期望为零。直观上，讨厌函数估错一点点，不在一阶改变目标方程。部分线性模型的正交实现是残差对残差：令 \\(\\hat V=D-\\hat m(X)\\)，\\(\\hat W=Y-\\hat g(X)\\)，用 \\(\\hat W\\) 对 \\(\\hat V\\) 的回归（或相应矩条件）去估 \\(\\theta\\)。\\(\\hat m\\) 把 \\(D\\) 中可由 \\(X\\) 预测的部分拿掉，于是正则化造成的 \\(g\\) 偏差不再通过 \\(D\\) 与 \\(X\\) 的相关泄漏进 \\(\\theta\\)。这与 Frisch–Waugh–Lovell 是同一几何，只是投影改成了机器学习。</p><p><span class="marginnote">正交不是识别。若 \\(D\\) 在给定 \\(X\\) 后仍与 \\(U\\) 相关——自我选择、反向因果、用同期收益当处理——DML 会给出一个很精确的错误答案。机器学习放大的是控制的灵活性，不是工具变量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>交叉拟合。</strong> 把样本分成 \\(K\\) 折。在第 \\(k\\) 折上，用其余折训练 \\(\\hat g^{(-k)}\\)、\\(\\hat m^{(-k)}\\)，只在第 \\(k\\) 折上计算残差与得分，最后把各折的得分堆起来解 \\(\\theta\\)。这样 \\(\\hat g\\) 不曾看见用来构造得分的那一行 \\(Y\\)，过拟合路径被切断。Chernozhukov 等人证明：若讨厌函数的均方误差以快于 \\(n^{-1/4}\\) 的速率消失，且得分正交，则 \\(\\hat\\theta\\) 仍是 \\(\\sqrt{n}\\) 正态。树与浅层网络在表格特征上常常可以满足这一速率；深层网络在小样本金融里则不一定。</p><p><strong>金融时间切分。</strong> 独立同分布交叉拟合会把未来日子的 \\(X\\) 模式泄漏给讨厌函数。合法做法是按时间块做交叉拟合，并在标签重叠处 <a href="/quant/purge-embargo">清洗与禁运</a>，与 <a href="/quant/cv-leakage-finance">交叉验证泄漏</a> 同一纪律。截面上同一天的股票高度相关，推断应在时间维聚类，而不是把 \\(N\\times T\\) 当成独立观测。这与 Fama–MacBeth 用时间序列标准差，精神一致。</p><h3 id="三种常见得分" tabindex="-1">三种常见得分 <a class="header-anchor" href="#三种常见得分" aria-label="Permalink to &quot;三种常见得分&quot;">​</a></h3><ol><li><strong>部分线性。</strong> 残差对残差，适合「在灵活控制特征后，连续处理的结构系数」。量化里可对应：某项制度持仓、某项已滞后的公司行为，在控制了大量可交易特征后的条件关联——仍须论证条件外生。</li><li><strong>交互 ATE。</strong> 分别估 \\(\\hat g(1,X)\\)、\\(\\hat g(0,X)\\) 与倾向 \\(\\hat\\pi(X)\\)，用增广逆概率加权（AIPW）得分。对指数调入、涨跌停制度、融券标的变更这类离散处理更自然，见与<a href="/quant/causal-tree-heterogeneity">因果树</a>的分工。</li><li><strong>工具变量。</strong> 第一阶段与结果方程的讨厌函数都可以 ML 化，正交得分对应去偏的 2SLS。弱工具问题不会因为换了森林而消失。</li></ol><p>讨厌函数的算法可以与 <a href="/quant/gbdt-alpha">GBDT</a> 相同，但验证目标是 \\(g\\) 与 \\(m\\) 的拟合，不是组合夏普。不要用同一验证集去挑能让 \\(\\hat\\theta\\) 最大的超参。</p><p><span class="marginnote">交叉拟合的折数在 Chernozhukov 等人的推荐里通常是 2 到 5。金融样本短，折太多会让每一折的讨厌函数更噪；折太少则浪费。应预指定 \\(K\\) 与时间块，而不是看 \\(\\theta\\) 的 \\(t\\) 值再改。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>偏差分解可以写成：目标估计量的误差 \\(\\approx\\) 正交得分的均值 \\(+\\) 讨厌误差的二阶项 \\(+\\) 过拟合交叉项。正交把第一阶讨厌误差清掉；交叉拟合把「用 \\(Y_i\\) 估 \\(g\\) 再拿 \\(Y_i\\) 算得分」的交叉项清掉。剩下的二阶项由 \\(n^{-1/4}\\) 速率压住。这就是「双重」：去偏一次（正交），再去过拟合一次（交叉拟合）。</p><p>与样本分割的朴素版本相比，交叉拟合不浪费一半数据做最终 \\(\\theta\\)。与双重稳健（Robins 派）的联系是：ATE 的 AIPW 得分在倾向或结果回归有一个正确时仍一致；DML 把其中的函数估计换成 ML，并补上正交与速率条件。量化研究里「双重稳健」常被误写成「两个模型都用了所以稳」——机制是得分的乘积结构，不是模型个数。</p><h3 id="和预测模型、风险模型不是同一张表" tabindex="-1">和预测模型、风险模型不是同一张表 <a class="header-anchor" href="#和预测模型、风险模型不是同一张表" aria-label="Permalink to &quot;和预测模型、风险模型不是同一张表&quot;">​</a></h3><p>预测模型最小化 \\(\\mathbb{E}[(Y-\\hat y(X))^2]\\)，系数不必有结构含义。<a href="/quant/factor-attribution">因子归因</a> 把已实现收益拆到载荷乘因子上，也不声称因果。DML 的 \\(\\theta\\) 只有在你声明的条件独立或工具有效时才是效应。把 DML 的 \\(t\\) 统计量拿去排因子库，会重新掉进 <a href="/quant/harvey-liu-zhu">多重检验</a>。正确用法是：预先指定一个处理、一套控制、一个识别故事，然后报告去偏点估计与聚类标准误，并做重叠与指定检验。</p><p>重叠失败时倾向接近 0 或 1，正交得分方差爆炸。金融处理（成为某个指数成份、进入融资标的）往往高度可由市值与行业预测，正是重叠最差的区域。应报告倾向分布，而不是只报告一个 \\(\\hat\\theta\\)。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>DML 不赦免前视。控制变量必须是决策或处理发生时的 <a href="/quant/point-in-time">点-in-time</a> 版本；用全样本主成分当 \\(X\\)，讨厌函数本身已经前视，正交无法补救。标签若是重叠的未来收益，得分的时间相关必须进入推断，简单的「正交所以 \\(t\\) 值可当 \\(z\\)」是错的。</p><p>不要把所有公司特征都叫做控制。若某一列是处理的下游（处理之后才实现的盈利、处理之后的分析师修正），控制它会挡住一部分效应，估计的是直接效应或被挡掉的偏差。控制集应在识别阶段写死。计算上，每折重训 GBDT 或网络代价高，但那是获得合法标准误的成本；用全样本 \\(\\hat g\\) 再对同一行算残差，回到论文明确警告的过拟合路径。</p><p>A 股的涨跌停与停牌使 \\(Y\\) 在部分日子不可实现，应把这些观测从结果方程拿掉或单独建模，否则 \\(g\\) 会去拟合不可交易的价格路径。处理若在这些日子无法发生，倾向模型也要反映制度，而不是假装随机指定。</p><p><span class="marginnote">在因子 zoo 上对每一个特征跑一遍「它当 \\(D\\)、其余当 \\(X\\) 的 DML」，得到的是一张去偏的相关表，不是一张因果发现表。预先指定处理，否则多重检验会把正交得分的渐近正态吃掉。</span></p>',29)),(n(),d(p,null,{default:r(()=>[u(o,{id:"mermaid-97",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8E%A7%E5%88%B6%20X%22%5D%20--%3E%20M%5B%22%E4%BA%A4%E5%8F%89%E6%8B%9F%E5%90%88%E4%BC%B0%20m%20%E4%B8%8E%20g%22%5D%0A%20%20D%5B%22%E5%A4%84%E7%90%86%20D%22%5D%20--%3E%20M%0A%20%20Y%5B%22%E7%BB%93%E6%9E%9C%20Y%22%5D%20--%3E%20M%0A%20%20M%20--%3E%20V%5B%22%E6%AE%8B%E5%B7%AE%20V%20%3D%20D%20-%20m(X)%22%5D%0A%20%20M%20--%3E%20W%5B%22%E6%AE%8B%E5%B7%AE%20W%20%3D%20Y%20-%20g(X)%22%5D%0A%20%20V%20--%3E%20TH%5B%22%E6%AD%A3%E4%BA%A4%E5%BE%97%E5%88%86%E8%A7%A3%20theta%22%5D%0A%20%20W%20--%3E%20TH%0A%20%20TH%20--%3E%20SE%5B%22%E6%97%B6%E9%97%B4%E8%81%9A%E7%B1%BB%E6%A0%87%E5%87%86%E8%AF%AF%22%5D%0A%20%20ID%5B%22%E8%AF%86%E5%88%AB%3A%20%E6%9D%A1%E4%BB%B6%E5%A4%96%E7%94%9F%E6%88%96%20IV%22%5D%20--%3E%20TH%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"Chernozhukov 等人的 DML 用 Neyman 正交得分加交叉拟合，使灵活机器学习估计讨厌函数时，低维目标仍可 \\(\\sqrt{n}\\) 推断。"),a("li",null,"部分线性模型的实现是残差对残差；ATE 用增广逆概率加权得分。正交防正则偏差，交叉拟合防过拟合交叉项。"),a("li",null,"识别不由算法提供。无条件外生或无有效工具时，精确的 \\(\\hat\\theta\\) 仍是关联。"),a("li",null,"金融须按时间块交叉拟合、处理标签重叠与截面相关；控制必须点-in-time，且不能包含处理的下游。"),a("li",null,[t("出处：Chernozhukov, Chetverikov, Demirer, Duflo, Hansen, Newey and Robins, "),a("em",null,"The Econometrics Journal"),t(", 2018；正交与双重稳健的前身见 Neyman、Robins 及相关半参数文献。")])],-1))])}const q=h(m,[["render",E]]);export{f as __pageData,q as default};
